// projects/novo-elements/src/elements/form/controls/timezone/TimezoneControl.ts
var TimezoneControl = class extends BaseControl {
  constructor(config3) {
    super("TimezoneControl", config3);
    this.controlType = "timezone";
    this.options = [];
    this.buildTimezones = (compareDate) => {
      const timezones = listTimeZones().map((zone) => {
        const timezone = findTimeZone(zone);
        const zonedTime = getZonedTime(compareDate, timezone);
        const formatted = formatZonedTime(zonedTime, `z - [${zone}] ([GMT] Z)`).replace("_", " ");
        const option = {
          value: zone,
          label: formatted,
          offset: zonedTime.zone.offset
        };
        return option;
      }).map((option) => {
        const rgx = /(^(\+|-)\d+\s- )/;
        const matches = option.label.match(rgx);
        if (matches) {
          const prefix = matches[0];
          option.label = option.label.split(prefix)[1];
        }
        return option;
      }).sort((a2, b2) => {
        const offsetDelta = b2.offset - a2.offset;
        if (offsetDelta !== 0) {
          return offsetDelta;
        }
        if (a2.label < b2.label) {
          return -1;
        }
        if (a2.label > b2.label) {
          return 1;
        }
        return 0;
      });
      return timezones;
    };
    this.options = this.buildTimezones(/* @__PURE__ */ new Date());
    this.placeholder = config3.placeholder || "";
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
    this.value = tz;
  }
};

