// projects/novo-elements/src/elements/form/extras/file/extras/file/File.ts
var NovoFile = class {
  constructor(file) {
    this.name = "";
    this.contentType = "";
    this.lastModified = 0;
    this.size = 0;
    this.loaded = false;
    this.reader = new FileReader();
    this.name = `${encodeURIComponent(file.name || "")}`;
    this.contentType = file.type;
    this.lastModified = file.lastModified;
    this.size = file.size;
    this.file = file;
    this.reader.onload = (event) => {
      this.fileContents = event.target.result.split(",")[1];
      this.dataURL = event.target.result;
      this.loaded = true;
      if (this.readPromise) {
        this.readPromise(this);
      }
    };
  }
  read() {
    return new Promise((resolve) => {
      this.readPromise = resolve;
      this.reader.readAsDataURL(this.file);
    });
  }
  toJSON() {
    return {
      name: this.name,
      contentType: this.type,
      lastModified: this.lastModified,
      size: this.size,
      fileContents: this.fileContents
    };
  }
};

