    component: DynamicFormFieldSetsExample,
    tsSource: `import%20%7B%20Component%20%7D%20from%20'%40angular%2Fcore'%3B%0Aimport%20%7B%20FormUtils%20%7D%20from%20'novo-elements'%3B%0Aimport%20%7B%20MockMetaHeaders%20%7D%20from%20'..%2FMockMeta'%3B%0A%0A%2F**%0A%20*%20%40title%20Dynamic%20Form%20Field%20Sets%20Example%0A%20*%2F%0A%40Component(%7B%0A%20%20%20%20selector%3A%20'dynamic-form-field-sets-example'%2C%0A%20%20%20%20templateUrl%3A%20'dynamic-form-field-sets-example.html'%2C%0A%20%20%20%20styleUrls%3A%20%5B'dynamic-form-field-sets-example.css'%5D%2C%0A%20%20%20%20standalone%3A%20false%2C%0A%7D)%0Aexport%20class%20DynamicFormFieldSetsExample%20%7B%0A%20%20public%20fieldsets%3A%20Array%3Cany%3E%3B%0A%20%20public%20fieldsetsForm%3A%20any%3B%0A%0A%20%20constructor(private%20formUtils%3A%20FormUtils)%20%7B%0A%20%20%20%20%2F%2F%20Dynamic%20%2B%20Fieldsets%0A%20%20%20%20this.fieldsets%20%3D%20formUtils.toFieldSets(%0A%20%20%20%20%20%20MockMetaHeaders%2C%0A%20%20%20%20%20%20'%24%20USD'%2C%0A%20%20%20%20%20%20%7B%7D%2C%0A%20%20%20%20%20%20%7B%20token%3A%20'TOKEN'%20%7D%2C%0A%20%20%20%20%20%20%7B%0A%20%20%20%20%20%20%20%20customfield%3A%20%7B%0A%20%20%20%20%20%20%20%20%20%20template%3A%20'custom-demo-component'%2C%0A%20%20%20%20%20%20%20%20%7D%2C%0A%20%20%20%20%20%20%7D%2C%0A%20%20%20%20)%3B%0A%20%20%20%20formUtils.setInitialValuesFieldsets(this.fieldsets%2C%20%7B%20firstName%3A%20'Initial%20F%20Name'%2C%20number%3A%2012%20%7D)%3B%0A%20%20%20%20this.fieldsetsForm%20%3D%20formUtils.toFormGroupFromFieldset(this.fieldsets)%3B%0A%20%20%7D%0A%0A%20%20save(form)%20%7B%0A%20%20%20%20if%20(!form.isValid)%20%7B%0A%20%20%20%20%20%20form.showOnlyRequired(true)%3B%0A%20%20%20%20%7D%20else%20%7B%0A%20%20%20%20%20%20alert('SAVING')%3B%0A%20%20%20%20%7D%0A%20%20%7D%0A%0A%20%20clear()%20%7B%0A%20%20%20%20this.fieldsets.forEach((fieldset)%20%3D%3E%20%7B%0A%20%20%20%20%20%20fieldset.controls.forEach((control)%20%3D%3E%20%7B%0A%20%20%20%20%20%20%20%20control.forceClear.emit()%3B%0A%20%20%20%20%20%20%7D)%3B%0A%20%20%20%20%7D)%3B%0A%20%20%7D%0A%0A%20%20onChange(value)%20%7B%0A%20%20%20%20console.info('I%20changed!'%2C%20value)%3B%0A%20%20%7D%0A%7D%0A`,
