        \u0275\u0275elementEnd();
        \u0275\u0275text(132, "\nnpm install novo-elements@7.2.0-next.0\n");
        \u0275\u0275elementEnd()();
        \u0275\u0275elementStart(133, "h2");
        \u0275\u0275text(134, "How to get it!");
        \u0275\u0275elementEnd();
        \u0275\u0275elementStart(135, "blockquote")(136, "div", 8);
        \u0275\u0275text(137, "Note: First follow the steps to update your angular app to ");
